CREATE TABLE "DispatchBoard" (id TEXT PRIMARY KEY,day TEXT NOT NULL,scope TEXT NOT NULL,"headSnapshotId" TEXT UNIQUE,"nextVersion" INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(day,scope));
CREATE TABLE "DispatchSnapshot" (id TEXT PRIMARY KEY,"boardId" TEXT NOT NULL REFERENCES "DispatchBoard"(id) ON DELETE RESTRICT,version INTEGER NOT NULL,"baseHeadId" TEXT,"sourceKind" TEXT NOT NULL CHECK ("sourceKind" IN ('manual_reviewed','workbook_fallback')),"sourceAsOf" TIMESTAMP(3) NOT NULL,"sourceRef" TEXT NOT NULL,coverage TEXT NOT NULL,note TEXT NOT NULL,slots JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'draft',"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),UNIQUE("boardId",version));
ALTER TABLE "DispatchBoard" ADD CONSTRAINT "DispatchBoard_headSnapshotId_fkey" FOREIGN KEY("headSnapshotId") REFERENCES "DispatchSnapshot"(id) ON DELETE RESTRICT;
CREATE TABLE "DispatchAllocation" (id TEXT PRIMARY KEY,"snapshotId" TEXT NOT NULL REFERENCES "DispatchSnapshot"(id) ON DELETE RESTRICT,"slotKey" TEXT NOT NULL,"unitId" TEXT NOT NULL REFERENCES "WarehouseUnit"(id) ON DELETE RESTRICT,"matchEvidence" JSONB NOT NULL,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"releasedAt" TIMESTAMP(3),"releaseReason" TEXT);
CREATE INDEX "DispatchAllocation_snapshotId_slotKey_idx" ON "DispatchAllocation"("snapshotId","slotKey");
CREATE UNIQUE INDEX "DispatchAllocation_active_slot" ON "DispatchAllocation"("snapshotId","slotKey") WHERE "releasedAt" IS NULL;
CREATE UNIQUE INDEX "DispatchAllocation_active_unit" ON "DispatchAllocation"("snapshotId","unitId") WHERE "releasedAt" IS NULL;
CREATE TABLE "DispatchReservation" ("unitId" TEXT PRIMARY KEY,"allocationId" TEXT NOT NULL UNIQUE REFERENCES "DispatchAllocation"(id) ON DELETE RESTRICT,"boardId" TEXT NOT NULL,"snapshotId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DispatchReservation_boardId_idx" ON "DispatchReservation"("boardId");
CREATE TABLE "DispatchWaveItem" (id TEXT PRIMARY KEY,"allocationId" TEXT NOT NULL UNIQUE REFERENCES "DispatchAllocation"(id) ON DELETE RESTRICT,"pickWaveId" TEXT NOT NULL REFERENCES "PickWave"(id) ON DELETE RESTRICT,"pickWaveItemId" TEXT NOT NULL UNIQUE REFERENCES "PickWaveItem"(id) ON DELETE RESTRICT,"unitId" TEXT NOT NULL,"snapshotId" TEXT NOT NULL);
CREATE INDEX "DispatchWaveItem_pickWaveId_unitId_idx" ON "DispatchWaveItem"("pickWaveId","unitId");
CREATE TABLE "DispatchFinalsSession" (id TEXT PRIMARY KEY,"boardId" TEXT NOT NULL REFERENCES "DispatchBoard"(id) ON DELETE RESTRICT,"snapshotId" TEXT NOT NULL UNIQUE REFERENCES "DispatchSnapshot"(id) ON DELETE RESTRICT,revision INTEGER NOT NULL DEFAULT 1,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"carriedSignoffs" JSONB NOT NULL DEFAULT '{}',"laneClearances" JSONB NOT NULL DEFAULT '{}');
CREATE TABLE "DispatchFinalsScan" (id TEXT PRIMARY KEY,"sessionId" TEXT NOT NULL REFERENCES "DispatchFinalsSession"(id) ON DELETE RESTRICT,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,fingerprint TEXT NOT NULL,"rawIdentifier" TEXT NOT NULL,"actualLane" TEXT NOT NULL,"expectedLane" TEXT,"unitId" TEXT,"physicalObservationId" TEXT NOT NULL,resolution TEXT NOT NULL,"candidateUnitIds" JSONB NOT NULL,outcome TEXT NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewStatus" TEXT NOT NULL DEFAULT 'open',"reviewedByUserId" TEXT,"reviewReason" TEXT,"reviewedAt" TIMESTAMP(3),"resolvedByScanId" TEXT,UNIQUE("sessionId","userId","eventId"));
CREATE INDEX "DispatchFinalsScan_sessionId_actualLane_receivedAt_idx" ON "DispatchFinalsScan"("sessionId","actualLane","receivedAt");
CREATE TABLE "DispatchFinalsCredit" (id TEXT PRIMARY KEY,"sessionId" TEXT NOT NULL REFERENCES "DispatchFinalsSession"(id) ON DELETE RESTRICT,"slotKey" TEXT NOT NULL,"allocationId" TEXT NOT NULL,"unitId" TEXT NOT NULL,lane TEXT NOT NULL,"confirmedAt" TIMESTAMP(3) NOT NULL,"scanId" TEXT NOT NULL,"physicalObservationId" TEXT NOT NULL,"carriedFromCreditId" TEXT,status TEXT NOT NULL DEFAULT 'confirmed',"invalidatedByScanId" TEXT,"invalidatedAt" TIMESTAMP(3));
CREATE INDEX "DispatchFinalsCredit_sessionId_lane_status_idx" ON "DispatchFinalsCredit"("sessionId",lane,status);
CREATE UNIQUE INDEX "DispatchFinalsCredit_active_slot" ON "DispatchFinalsCredit"("sessionId","slotKey") WHERE status='confirmed';
CREATE UNIQUE INDEX "DispatchFinalsCredit_active_unit" ON "DispatchFinalsCredit"("sessionId","unitId") WHERE status='confirmed';
CREATE TABLE "DispatchLaneSignoff" (id TEXT PRIMARY KEY,"sessionId" TEXT NOT NULL REFERENCES "DispatchFinalsSession"(id) ON DELETE RESTRICT,lane TEXT NOT NULL,version INTEGER NOT NULL,"snapshotId" TEXT NOT NULL,"sourceAsOf" TIMESTAMP(3) NOT NULL,payload JSONB NOT NULL,"payloadHash" TEXT NOT NULL,"signedByUserId" TEXT NOT NULL,"signedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("sessionId",lane,version));
CREATE TABLE "DispatchAmendment" (id TEXT PRIMARY KEY,"sessionId" TEXT NOT NULL REFERENCES "DispatchFinalsSession"(id) ON DELETE RESTRICT,lane TEXT NOT NULL,reason TEXT NOT NULL,"affectedSlotKeys" JSONB NOT NULL,"priorSignoffId" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedBySignoffId" TEXT,"resolvedAt" TIMESTAMP(3));
CREATE INDEX "DispatchAmendment_sessionId_lane_resolvedAt_idx" ON "DispatchAmendment"("sessionId",lane,"resolvedAt");
CREATE TABLE "DispatchEvent" (id TEXT PRIMARY KEY,"boardId" TEXT NOT NULL,"snapshotId" TEXT,"sessionId" TEXT,action TEXT NOT NULL,"userId" TEXT NOT NULL,note TEXT NOT NULL,payload JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DispatchEvent_boardId_createdAt_idx" ON "DispatchEvent"("boardId","createdAt");
CREATE TABLE "DispatchCommandReceipt" (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"operationId" TEXT NOT NULL,fingerprint TEXT NOT NULL,result JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","operationId"));
INSERT INTO "RoleBundle" (id,name,description,capabilities,"isSystem","updatedAt") VALUES ('dispatch-lead','Dispatch lead','Explicit allocation and lane sign-off authority; not assigned by migration',ARRAY['inventory.read','workflow.read','workflow.execute','dispatch.allocate','dispatch.signoff'],false,CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
UPDATE "RoleBundle" SET capabilities=ARRAY(SELECT DISTINCT unnest(capabilities||ARRAY['dispatch.allocate','dispatch.signoff'])),"updatedAt"=CURRENT_TIMESTAMP WHERE id='legacy-admin';
